from pathlib import Path
p=Path('app-v2.mjs'); lines=p.read_text(encoding='utf-8').splitlines()
for i,line in enumerate(lines):
    if line.startswith('const audioCache=new Map()'): lines[i]="const audioCache=new Map(),audioPending=new Map(),decodedAudioCache=new Map(),decodedAudioPending=new Map(),pageAudioWarmPending=new Map();"
    elif line.startswith('function voiceNeedsPriority()'): lines[i]="function voiceNeedsPriority(){if(!speaking||$('voice').value==='system:browser')return false;const tail=audioTimeline[audioTimeline.length-1],ahead=tail?tail.idx-sentenceIndex:0;return audioFillRunning||ahead<3;}"
    elif line.startswith('async function warmNextPages'): lines[i]="async function warmNextPages(fromPage,count=(knownBookProfile?.prefetchPages||10)){const generation=++preloadGeneration,targets=[];for(let n=fromPage+1;n<=Math.min(pdf.numPages,fromPage+count);n++)if(!translationCache.has(n))targets.push(n);if(!targets.length){if(!speaking)setBuffer(`pr\\u00f3ximas ${Math.min(count,pdf.numPages-fromPage)} prontas`,true);return;}let ready=0;if(!speaking)setBuffer(`buffer 0/${targets.length} p\\u00e1ginas`);for(const n of targets){if(generation!==preloadGeneration)return;try{await translatePage(n,{foreground:false});ready++;}catch(e){console.warn('prefetch_failed',n,e);}if(!speaking)setBuffer(`buffer ${ready}/${targets.length} p\\u00e1ginas`,ready===targets.length);await new Promise(r=>setTimeout(r,speaking?220:90));}}"
    elif line.startswith('async function warmCurrentAudio'): lines[i]="async function warmCurrentAudio(record,count=4,startIndex=sentenceIndex){if($('voice').value==='system:browser')return;const all=(record?.segments?.length?record.segments:fallbackSegments(record?.sourceText||'',record?.translatedText||'')).filter(x=>String(x?.target||'').trim()),start=Math.max(0,Math.min(startIndex,Math.max(0,all.length-1))),segs=all.slice(start,start+Math.max(1,count));if(!segs.length)return;let ready=0;if(!speaking)setBuffer(`pr\\u00e9-aquecendo Jarvis 0/${segs.length}`);for(const seg of segs){try{await getDecodedAudio(String(seg.target||''));ready++;if(!speaking)setBuffer(`Jarvis pronto ${ready}/${segs.length}`,ready===segs.length);}catch(e){console.warn('warm_audio_failed',e);break;}await new Promise(r=>setTimeout(r,25));}}"
    elif line.startswith('async function getDecodedAudio'): lines[i]="async function getDecodedAudio(text){const voice=$('voice').value,spoken=prepareNarrationText(text),key=`${knownBookId}|${voice}|${spoken}`;if(decodedAudioCache.has(key))return decodedAudioCache.get(key);if(decodedAudioPending.has(key))return decodedAudioPending.get(key);const job=(async()=>{const blob=await getLocalAudio(spoken);await ensureAudioContext();const bytes=await blob.arrayBuffer(),buffer=trimAudioBuffer(await audioContext.decodeAudioData(bytes.slice(0)));decodedAudioCache.set(key,buffer);if(decodedAudioCache.size>120)decodedAudioCache.delete(decodedAudioCache.keys().next().value);return buffer;})();decodedAudioPending.set(key,job);try{return await job;}finally{decodedAudioPending.delete(key);}}"
    elif line.startswith('function narrationGap'): lines[i]=line+"\nfunction audioAheadCount(){const tail=audioTimeline[audioTimeline.length-1];return tail?Math.max(0,tail.idx-sentenceIndex):0;}\nasync function waitForAudioIdle(){while((speaking&&!paused&&(audioFillRunning||audioAheadCount()<3))||(!speaking&&(audioPending.size>0||decodedAudioPending.size>0)))await new Promise(r=>setTimeout(r,120));}\nasync function warmPageAudio(n,count=10){if(!pdf||n<1||n>pdf.numPages||$('voice').value==='system:browser')return;const key=`${documentKey()}|${$('voice').value}|${n}|${count}`;if(pageAudioWarmPending.has(key))return pageAudioWarmPending.get(key);const job=(async()=>{const record=await translatePage(n,{foreground:false}),segs=(record?.segments?.length?record.segments:fallbackSegments(record?.sourceText||'',record?.translatedText||'')).filter(x=>String(x?.target||'').trim()).slice(0,Math.max(1,count));for(const seg of segs){await waitForAudioIdle();try{await getDecodedAudio(String(seg.target||''));}catch(e){console.warn('warm_page_audio_failed',n,e);break;}}})();pageAudioWarmPending.set(key,job);try{return await job;}finally{pageAudioWarmPending.delete(key);}}\nasync function warmAheadAudio(fromPage){if(!pdf||$('voice').value==='system:browser')return;await warmPageAudio(fromPage+1,12);if(fromPage+2<=pdf.numPages)await warmPageAudio(fromPage+2,6);}"
    elif line.startswith('async function fillAudioSchedule'): lines[i]=line.replace("loadPage(page+1,{autoplay:true})","loadPage(page+1,{autoplay:true,seamless:true})",1)
    elif line.startswith('async function startLocalContinuous'): lines[i]="async function startLocalContinuous(){if(!speaking||paused)return;await ensureAudioContext();const generation=audioScheduleGeneration,text=String(currentSegments[sentenceIndex]?.target||''),key=`${knownBookId}|${$('voice').value}|${prepareNarrationText(text)}`,ready=decodedAudioCache.has(key);setBuffer(ready?'voz local \\u2022 buffer antecipado pronto':'preparando fluxo cont\\u00ednuo',ready);fillAudioSchedule(generation);scheduleHighlightLoop(generation);}"
    elif line.startswith('async function loadPage'): lines[i]="async function loadPage(n,{autoplay=false,preservePending=false,seamless=false}={}){if(!pdf)return;const token=++pageLoadToken;preloadGeneration++;const seamlessLocal=!!(seamless&&autoplay&&speaking&&!paused&&$('voice').value!=='system:browser');if(seamlessLocal)clearScheduledAudio();else stopSpeech();if(!preservePending){pendingSentenceIndex=null;pendingSentenceOffset=0;currentSentenceOffset=0;}currentSegments=[];sourceRanges=[];pdfTextGeometry=[];currentHighlightProgress=0;page=Math.min(Math.max(1,n),pdf.numPages);$('pageNum').value=page;$('pageTotal').textContent=`/ ${pdf.numPages}`;setStatus(isNativeBook()?`P\\u00e1gina ${page}: preparando texto original em portugu\\u00eas...`:`P\\u00e1gina ${page}: preparando tradu\\u00e7\\u00e3o em portugu\\u00eas...`);setBuffer(seamlessLocal?'transi\\u00e7\\u00e3o de p\\u00e1gina \\u2022 usando buffer antecipado':'prioridade: p\\u00e1gina atual',seamlessLocal);renderPdfPage(page).catch(e=>{$('pdfLoading').classList.remove('show');console.error('pdf_render_failed',e);});try{const target=page,record=await translatePage(target,{foreground:true});if(token!==pageLoadToken||target!==page)return;renderSegments(record);setStatus(isNativeBook()?`P\\u00e1gina ${page} pronta \\u2022 livro pr\\u00e9-analisado \\u2022 texto original PT-BR`:`P\\u00e1gina ${page} pronta \\u2022 ${knownBookProfile?'livro pr\\u00e9-analisado \\u2022 ':''}${record.engine?.includes('literal')?'tradu\\u00e7\\u00e3o r\\u00e1pida':'tradu\\u00e7\\u00e3o editorial contextualizada'}`);const prefetch=knownBookProfile?.prefetchPages||10;setBuffer(seamlessLocal?'pr\\u00f3xima p\\u00e1gina j\\u00e1 estava em buffer':`p\\u00e1gina atual pronta \\u2022 preparando pr\\u00f3ximas ${prefetch}`,true);saveProgress();const warmCount=Math.min(4,Number(knownBookProfile?.warmSentences||4));setTimeout(()=>warmCurrentAudio(record,warmCount,sentenceIndex),50);setTimeout(()=>warmAheadAudio(target),130);setTimeout(()=>analyzeDocumentBackground(),100);setTimeout(()=>warmNextPages(target,prefetch),180);if(autoplay&&record.translatedText&&token===pageLoadToken){if(seamlessLocal){speaking=true;paused=false;$('play').textContent='\\u23f8 Pausar';$('play').classList.add('playing');updateHighlights();startLocalContinuous();}else startSpeech();}}catch(e){if(token!==pageLoadToken)return;stopSpeech();currentSegments=[];updateHighlights();$('translation').innerHTML='<div class=\"empty\">N\\u00e3o consegui traduzir esta p\\u00e1gina.<br><br><button class=\"btn\" id=\"retryTranslation\">Tentar novamente</button></div>';setStatus(`Falha na tradu\\u00e7\\u00e3o: ${String(e.message||e)}`);setBuffer('tradu\\u00e7\\u00e3o indispon\\u00edvel');$('retryTranslation')?.addEventListener('click',()=>{translationCache.delete(page);loadPage(page);});}}"
p.write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('patched')